 public static void main(String[] args){DomainSession s=new DomainSession();DomainSessionIndex.all.add(s);class_1308 neutral=new class_1308();neutral.x=10;s.entities.add(neutral);s.mask=4;check(!DomainObjects.matches(s,"D26",neutral),"neutral became hostile");s.mask=2;check(DomainObjects.matches(s,"D26",neutral),"neutral selection");s.mask=0;check(!DomainObjects.matches(s,"D26",neutral),"empty selection");s.mask=8;DomainObjects.attacked(s.player,neutral);check(DomainObjects.matches(s,"D26",neutral),"active attack enrollment");DomainSession other=new DomainSession();other.mask=8;check(!DomainObjects.matches(other,"D26",neutral),"active enrollment leaked to another owner");s.mask=16;check(!DomainObjects.matches(s,"D26",neutral),"idle mob passive");neutral.target=s.player;check(DomainObjects.matches(s,"D26",neutral),"attack AI passive");neutral.target=null;neutral.brainTarget=s.player;check(DomainObjects.matches(s,"D26",neutral),"Brain attack passive");neutral.brainTarget=null;neutral.navigation.path=new class_11();neutral.navigation.path.destination=new class_2338(0,0,0);check(DomainObjects.matches(s,"D26",neutral),"approaching path passive");neutral.navigation.path.finished=true;check(!DomainObjects.matches(s,"D26",neutral),"finished path passive");s.mask=1|2|4;neutral.relation=4;check(DomainObjects.matches(s,"D26",neutral),"boss hostile category");check(!DomainObjects.matches(s,"D26",s.player),"friendly must not include self");s.mask|=DomainObjects.SELF;check(DomainObjects.matches(s,"D26",s.player),"separate self category");s.mask=DomainObjects.SELF;check(!DomainObjects.matches(s,"D26",neutral),"self-only included another creature");s.mask=DomainObjects.ALL_CREATURES;neutral.inside=false;check(!DomainObjects.matches(s,"D62",neutral)&&DomainObjects.qualifies(s,"D62",neutral),"entry teleport requires relation without current membership");neutral.inside=true;neutral.alive=false;check(DomainObjects.matches(s,"D49",neutral),"death hook cannot select dying entity");s.mask=0;neutral.relation=3;check(!DomainObjects.configurable("D09")&&!DomainObjects.configurable("D55"),"companion selectors enabled");check(DomainObjects.matches(s,"D09",neutral),"disabled selector changed original enemy scope");check(DomainObjects.configurable("D40")&&DomainObjects.configurable("D60")&&DomainObjects.configurable("D63"),"protective selectors disabled");check(DomainObjects.defaultMask("D40")==33&&DomainObjects.defaultMask("D60")==33&&DomainObjects.defaultMask("D63")==33,"protective default targets");check(DomainObjects.defaultMask("D64")==4,"mining fatigue default");System.out.println("PASS: category union, empty selection, per-owner active attacks, combat/Brain/navigation passive AI, finished paths, bosses, teleport entry, death hooks");}
